1	/**
2	 * The checksummed forms: `b58encode_check` and `b58decode_check`.
3	 *
4	 * A four-byte checksum — the first four bytes of the doubled SHA-256 of the
5	 * payload — is appended to the payload before base58 encoding, and verified
6	 * after decoding.
7	 */
8	
9	import { PyValueError } from '../errors.mjs';
10	import { sha256d } from '../sha256.mjs';
11	import { BITCOIN_ALPHABET } from './alphabet.mjs';
12	import { b58decode, b58encode } from './core.mjs';
13	import { scrubInput } from './scrub.mjs';
14	
15	const CHECKSUM_LENGTH = 4;
16	
17	function checksum(payload) {
18	  return sha256d(payload).slice(0, CHECKSUM_LENGTH);
19	}
20	
21	/** Encode a byte array with its checksum appended. */
22	export function b58encodeCheck(v, options = {}) {
23	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
24	  const payload = scrubInput(v);
25	  return b58encode(payload.concat(checksum(payload)), { alphabet });
26	}
27	
28	/** Decode a checksummed value, returning the payload without its checksum. */
29	export function b58decodeCheck(v, options = {}) {
30	  const alphabet = options.alphabet || BITCOIN_ALPHABET;
31	  const decoded = b58decode(v, { alphabet });
32	
33	  const payload = decoded.slice(0, decoded.length - CHECKSUM_LENGTH);
34	  const check = decoded.slice(decoded.length - CHECKSUM_LENGTH);
35	  const expected = checksum(payload);
36	
37	  const matches =
38	    check.length === expected.length && check.every((byte, i) => byte === expected[i]);
39	  if (!matches) throw new PyValueError('Invalid checksum');
40	
41	  return payload;
42	}
