1	/**
2	 * Python `bytes` modelled as a plain JS array of integers in 0-255, together
3	 * with the codecs that produce them and the `repr()` that prints them.
4	 *
5	 * Byte sequences are deliberately plain arrays: no typed-array or binary-buffer
6	 * abstraction is used anywhere in this port.
7	 */
8	
9	import { PyUnicodeEncodeError } from './errors.mjs';
10	import { escapeCodePoint } from './pystr.mjs';
11	import { isBytesSpace } from './unicode.mjs';
12	
13	/**
14	 * Build the message CPython raises when a codec cannot encode part of a string.
15	 * A maximal run of unencodable characters is reported as one error, and the
16	 * noun is pluralised when the run is longer than one character.
17	 */
18	function encodeErrorMessage(codec, cps, start, end, reason) {
19	  if (end - start === 1) {
20	    return `'${codec}' codec can't encode character ${"'" + escapeCodePoint(cps[start]) + "'"} in position ${start}: ${reason}`;
21	  }
22	  return `'${codec}' codec can't encode characters in position ${start}-${end - 1}: ${reason}`;
23	}
24	
25	/** Python's `str.encode('ascii')`. */
26	export function asciiEncode(str) {
27	  const cps = [];
28	  for (const ch of str) cps.push(ch.codePointAt(0));
29	  for (let i = 0; i < cps.length; i += 1) {
30	    if (cps[i] > 0x7f) {
31	      let end = i + 1;
32	      while (end < cps.length && cps[end] > 0x7f) end += 1;
33	      throw new PyUnicodeEncodeError(
34	        encodeErrorMessage('ascii', cps, i, end, 'ordinal not in range(128)'),
35	      );
36	    }
37	  }
38	  return cps;
39	}
40	
41	/** Python's `str.encode()` — i.e. UTF-8, which rejects surrogates. */
42	export function utf8Encode(str) {
43	  const cps = [];
44	  for (const ch of str) cps.push(ch.codePointAt(0));
45	  const out = [];
46	  for (let i = 0; i < cps.length; i += 1) {
47	    const cp = cps[i];
48	    if (cp >= 0xd800 && cp <= 0xdfff) {
49	      let end = i + 1;
50	      while (end < cps.length && cps[end] >= 0xd800 && cps[end] <= 0xdfff) end += 1;
51	      throw new PyUnicodeEncodeError(
52	        encodeErrorMessage('utf-8', cps, i, end, 'surrogates not allowed'),
53	      );
54	    }
55	    if (cp < 0x80) {
56	      out.push(cp);
57	    } else if (cp < 0x800) {
58	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
59	    } else if (cp < 0x10000) {
60	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
61	    } else {
62	      out.push(
63	        0xf0 | (cp >> 18),
64	        0x80 | ((cp >> 12) & 0x3f),
65	        0x80 | ((cp >> 6) & 0x3f),
66	        0x80 | (cp & 0x3f),
67	      );
68	    }
69	  }
70	  return out;
71	}
72	
73	/** Python's `bytes.decode('ascii')`, for turning byte values back into chars. */
74	export function asciiDecode(bytes) {
75	  let out = '';
76	  for (const b of bytes) out += String.fromCharCode(b);
77	  return out;
78	}
79	
80	/** `bytes.lstrip(<single byte>)`. */
81	export function lstripByte(bytes, byte) {
82	  let start = 0;
83	  while (start < bytes.length && bytes[start] === byte) start += 1;
84	  return bytes.slice(start);
85	}
86	
87	/** `bytes.rstrip()` — trailing b' \t\n\r\x0b\f'. */
88	export function rstripBytes(bytes) {
89	  let end = bytes.length;
90	  while (end > 0 && isBytesSpace(bytes[end - 1])) end -= 1;
91	  return bytes.slice(0, end);
92	}
93	
94	/**
95	 * Python's `repr()` of a bytes object, which is what `print(b'...')` writes.
96	 *
97	 * The literal is single quoted unless the value contains a single quote and no
98	 * double quote.  Only `\\`, `\t`, `\n`, `\r` and the delimiter get short
99	 * escapes; every other non-printable byte becomes lowercase `\xNN`.
100	 */
101	export function bytesRepr(bytes) {
102	  let hasSingle = false;
103	  let hasDouble = false;
104	  for (const b of bytes) {
105	    if (b === 0x27) hasSingle = true;
106	    else if (b === 0x22) hasDouble = true;
107	  }
108	  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
109	  let body = '';
110	  for (const b of bytes) {
111	    if (b === quote || b === 0x5c) body += '\\' + String.fromCharCode(b);
112	    else if (b === 0x09) body += '\\t';
113	    else if (b === 0x0a) body += '\\n';
114	    else if (b === 0x0d) body += '\\r';
115	    else if (b >= 0x20 && b < 0x7f) body += String.fromCharCode(b);
116	    else body += '\\x' + b.toString(16).padStart(2, '0');
117	  }
118	  const q = String.fromCharCode(quote);
119	  return 'b' + q + body + q;
120	}
