1	/**
2	 * Python `str` operations that the reference program's behaviour depends on,
3	 * plus the `repr()` spellings that appear inside its error messages.
4	 */
5	
6	import { isPySpace } from './unicode.mjs';
7	
8	/** Code points of a JS string, so indices count characters the way Python does. */
9	export function codePoints(str) {
10	  const out = [];
11	  for (const ch of str) out.push(ch.codePointAt(0));
12	  return out;
13	}
14	
15	/** Python's `str.rstrip()` — trailing Unicode whitespace only. */
16	export function rstripPyStr(str) {
17	  let end = str.length;
18	  while (end > 0) {
19	    const cp = str.codePointAt(end - 1);
20	    // A trailing low surrogate is never whitespace, so code-unit stepping is safe.
21	    if (!isPySpace(cp)) break;
22	    end -= 1;
23	  }
24	  return str.slice(0, end);
25	}
26	
27	/** Python's `str.strip()` — leading and trailing Unicode whitespace. */
28	export function stripPyStr(str) {
29	  let start = 0;
30	  let end = str.length;
31	  while (start < end && isPySpace(str.codePointAt(start))) start += 1;
32	  while (end > start && isPySpace(str.codePointAt(end - 1))) end -= 1;
33	  return str.slice(start, end);
34	}
35	
36	/**
37	 * The `\x`/`\u`/`\U` escape CPython uses for a code point inside a codec error
38	 * message, where non-ASCII is always escaped regardless of printability.
39	 */
40	export function escapeCodePoint(cp) {
41	  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
42	  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
43	  return '\\U' + cp.toString(16).padStart(8, '0');
44	}
45	
46	/**
47	 * Python's `repr()` of a one-character string, as interpolated by
48	 * `"Invalid character {!r}"`.  A lone `'` flips the literal to double quotes.
49	 */
50	export function reprChar(cp) {
51	  const quote = cp === 0x27 ? '"' : "'";
52	  let body;
